function predict_sR(branch_pc):
    sR_sum = 0
    for b = 0 to 7:
        // Bank 0 covers 9 registers (k=0..8: R0, R8, ..., R64); Banks 1-7 cover 8 registers (k=0..7: R[b + 8*k])
        num_regs_in_bank = 9 if b == 0 else 8
        bank_valid_regs = []
        for k = 0 to num_regs_in_bank - 1:
            r = b + 8 * k
            if reg_table[r].valid == 1:
                bank_valid_regs.append((r, k))

        if len(bank_valid_regs) == 0:
            continue // Bank contribution is 0 (x0)

        // Query UT0, UT1, UT2 for this bank
        idx0 = hash_ut(branch_pc, 0, b)
        idx1 = hash_ut(branch_pc, 1, b)
        idx2 = hash_ut(branch_pc, 2, b)

        best_reg = NULL
        max_useful = -9999
        for (r, k) in bank_valid_regs:
            u = UT[b][0][idx0][k] + UT[b][1][idx1][k] + UT[b][2][idx2][k]
            if u > max_useful:
                max_useful = u
                best_reg = r

        // Record chosen register and bank availability for training update
        pred_snapshot.bank_valid_regs[b] = [r for (r, k) in bank_valid_regs]
        pred_snapshot.selected_reg[b] = best_reg
        pred_snapshot.max_useful[b] = max_useful

        // Select digest and compute bank WT contribution
        if max_useful > 0:
            digest = reg_table[best_reg].payload & 0x0FFF
            h0 = hash_wt(branch_pc, digest, 0) % 512
            h1 = hash_wt(branch_pc, digest, 1) % 256
            h2 = hash_wt(branch_pc, digest, 2) % 128

            w_sum = WT[b][0][h0] + WT[b][1][h1] + WT[b][2][h2]
            bank_contrib = floor(w_sum * 2.5)
            sR_sum += bank_contrib
        else:
            // Non-useful bank contribution is suppressed by multiplying by 0
            pass

    return sR_sum

function generate_digest(reg_type, reg_value):
    if reg_type == 0:
        trailing = count_trailing_zeros(reg_value) & 0x3F
        leading = count_leading_zeros(reg_value) & 0x3F
        lsb6 = reg_value & 0x3F
        return (trailing ^ (leading << 3) ^ (lsb6 << 6)) & 0x0FFF
    elif reg_type == 1:
        return ((reg_value >> 55) & 0x1FF) << 3
    elif reg_type == 2:
        flags = reg_value & 0x0F
        return flags | (flags << 4) | (flags << 8)
    return 0

function on_complete(dest_reg, rob_tag, reg_value, reg_type):
    if dest_reg >= 0 and dest_reg < 65:
        // Verify completing instruction matches current occupant
        if reg_table[dest_reg].valid == 0 and reg_table[dest_reg].payload == (rob_tag & 0x3FFF):
            digest = generate_digest(reg_type, reg_value)
            reg_table[dest_reg].payload = digest & 0x0FFF  // 12-bit digest
            reg_table[dest_reg].valid = 1
            reg_table[dest_reg].decay_ctr = 0

function on_decode(dest_reg, rob_tag):
    for r = 0 to 64:
        if reg_table[r].valid == 1:
            reg_table[r].decay_ctr = reg_table[r].decay_ctr + 1
            if reg_table[r].decay_ctr >= 256:
                reg_table[r].valid = 0
    if dest_reg >= 0 and dest_reg < 65:
        reg_table[dest_reg].valid = 0
        reg_table[dest_reg].payload = rob_tag & 0x3FFF  // 14-bit ROB tag
        reg_table[dest_reg].decay_ctr = 0

function saturating_add(ref_val, delta, min_val, max_val):
    return min(max_val, max(min_val, ref_val + delta))

function register_index_in_bank(reg_id, bank_id):
    return reg_id // 8

function update_sR(branch_pc, actual_dir, sc_correct, pred_snapshot):
    for b = 0 to 7:
        valid_regs = pred_snapshot.bank_valid_regs[b]
        if valid_regs is empty:
            continue

        // Training rule: randomly select one available register within the bank
        reg_to_update = valid_regs[random_choice(len(valid_regs))]
        sub_idx = register_index_in_bank(reg_to_update, b)

        idx0 = hash_ut(branch_pc, 0, b)
        idx1 = hash_ut(branch_pc, 1, b)
        idx2 = hash_ut(branch_pc, 2, b)

        // Update usefulness weights in UT (increment if this bank predicted correctly, decrement if wrong)
        ut_dir = +1 if (sc_correct) else -1
        UT[b][0][idx0][sub_idx] = saturating_add(UT[b][0][idx0][sub_idx], ut_dir, -32, 31)
        UT[b][1][idx1][sub_idx] = saturating_add(UT[b][1][idx1][sub_idx], ut_dir, -32, 31)
        UT[b][2][idx2][sub_idx] = saturating_add(UT[b][2][idx2][sub_idx], ut_dir, -32, 31)

        // Update prediction weights in WT for this register's digest
        digest = reg_table[reg_to_update].payload & 0x0FFF
        h0 = hash_wt(branch_pc, digest, 0) % 512
        h1 = hash_wt(branch_pc, digest, 1) % 256
        h2 = hash_wt(branch_pc, digest, 2) % 128

        wt_dir = +1 if (actual_dir == TAKEN) else -1
        WT[b][0][h0] = saturating_add(WT[b][0][h0], wt_dir, -32, 31)
        WT[b][1][h1] = saturating_add(WT[b][1][h1], wt_dir, -32, 31)
        WT[b][2][h2] = saturating_add(WT[b][2][h2], wt_dir, -32, 31)
